  /* ============================================================
     图鉴（跨周目累积，localStorage 单独存）
     bg / char 在剧情里出现过就自动收录；lore 靠文本关键词点亮
     ============================================================ */
  gallery: {
    bg: {
      title_stairs:     { name: "雪夜的单元门", desc: "红旗小区三单元。门半开着，楼上有一扇窗亮着。" },
      stairs_night:     { name: "坏了半年的那盏灯", desc: "三楼那盏感应灯。九点四十，她每天从这里上楼。" },
      wan_bedroom:      { name: "她的房间", desc: "奶油白和浅木色。父亲走后，她在这里读完了一整个高三。" },
      study_night:      { name: "父亲的书房", desc: "书架第三层，一本《刑法》后面，藏着一个牛皮纸袋。" },
      busstation_night: { name: "雾川长途站", desc: "二〇二二年冬，晚上七点。他背一个包，从这儿进城。" },
      rooftop_dusk:     { name: "修车行天台", desc: "站在这里，能看见四楼那扇亮到十一点的窗。" },
      jiang_room:       { name: "他的临时住处", desc: "城中村隔断房。一张床，一个电磁炉，一扇关不严的窗。" },
      new_year_steps:   { name: "除夕的门灯", desc: "台阶上落着雪，雪里是爆竹的红纸。门里有人等着，门口有人不敢进去。" },
      teahouse_day:     { name: "城南老茶厂的茶室", desc: "塑料布封着窗，暖气片上烤着橘子。郑维成第一次主动约人，约在这种地方。" },
      garage_day:       { name: "城西修车行 · 白天", desc: "卷帘门卷到一半，面包车架在千斤顶上。老板扣他两百块，管他叫「野狗」。" },
      prison_yard:      { name: "放风场", desc: "三面是墙，一面是铁门，头顶那一小块白天得刺眼。他在这儿学会了把四十分钟站完。" },
      summer_alley:     { name: "夏天的过道", desc: "补习班楼下的那条道。晾着的白衬衫、滴水的空调外机、梧桐叶。她一个人走过一整个八月。" }
    },
    char: {
      jiang: {
        normal: { name: "江野 · 沉默", desc: "手插在口袋里。他在忍，忍的时候就是这样。" },
        pale:   { name: "江野 · 苍白", desc: "狱里落下的毛病。灯太亮、人太多，脸就白。" },
        tense:  { name: "江野 · 紧绷", desc: "肩线绷成一条。下一秒要么动手，要么转身走。" },
        smirk:  { name: "江野 · 似笑非笑", desc: "他最危险的表情。不是开心，是准备咬人。" },
        hurt:   { name: "江野 · 受伤", desc: "嘴角有血。他说没事，然后自己擦了。" }
      },
      wan: {
        normal: { name: "万宁 · 平静", desc: "十九岁，复读高三。她说「你查过我爸的案卷，对吧」的时候，就是这个表情。" },
        calm:   { name: "万宁 · 冷淡", desc: "不生气，也不心软。只是把话放在桌上，让你自己看。" },
        sharp:  { name: "万宁 · 看穿", desc: "她看人的时候，像在念一份已经写完的笔录。" },
        soft:   { name: "万宁 · 松下来", desc: "两本旧课本抱在胸前，低头，笑了一点点——只有确定对方不会走的时候，她才这样。" },
        hurt:   { name: "万宁 · 忍", desc: "眼眶红了，下巴内收，咬着下唇。手把裙子捏出一道褶——她哭过，但从不在人前哭完。" }
      }
    },
    lore: [
      { id: "wuchuan", name: "雾川市", kw: ["雾川"], desc: "北方老工业小城。冬天很长，人情很密，一个楼道里的事，整栋楼都知道。" },
      { id: "hongqi", name: "红旗小区", kw: ["红旗小区"], desc: "女主家的老小区。三单元，楼道三楼那盏灯坏了半年，物业一直没修。" },
      { id: "laowan", name: "万建军", kw: ["万建军"], desc: "万宁的父亲，雾川市局刑警，从警二十三年。二〇二一年冬坠楼身亡，定性意外。" },
      { id: "zheng", name: "郑维成", kw: ["郑维成"], desc: "江野生父的表兄，当年的市局领导，如今下海的「成功企业家」。七年前抽走家暴记录的人。" },
      { id: "anjuan", name: "案卷节选", kw: ["案卷"], desc: "江野出狱第三天，花两百块托人弄到的复印件。第三页右上角，经办人签名：万建军。" },
      { id: "yimi", name: "一米一的护栏", kw: ["一米一"], desc: "城东那栋写字楼天台的高度。人一米七五，风一吹，一米一什么也拦不住。" },
      { id: "daoshan", name: "折叠刀", kw: ["折叠刀"], desc: "他包里三样东西之一。没用过，也不打算用。他给自己定的规矩：吓可以，伤不行。" },
      { id: "acan", name: "阿灿", kw: ["阿灿"], desc: "江野狱中结识的兄弟，出狱后在修车行打工。嘴碎，忠诚，关键时刻替他挡事。" },
      { id: "liujie", name: "刘姐", kw: ["刘姐"], desc: "城东那栋楼三楼的住户。二〇二一年冬，她听见一句「你收手吧」，还看见天台上站着一个年轻男人。" },
      { id: "tiantai", name: "修车行天台", kw: ["修车行"], desc: "他打零工的地方。晚上坐在天台上抽烟，能看见她家四楼那扇窗。" },
      { id: "yaoshi", name: "旧钥匙", kw: ["钥匙"], desc: "父亲书房的那把。她给了他。这不是家门的钥匙，是从今往后也算他一份的意思。" },
      { id: "huikuan", name: "匿名汇款", kw: ["汇款", "打钱", "医药费"], desc: "服刑那六年，有人用别人的名字，每月往一个账户里打钱。够他妈吃饭，够请一个白班护工。" }
    ]
  },

