/* ============================================================
   两篇手稿彩蛋的正文在 eggs.js（Base64），这里接回节点树
   ============================================================ */
if (typeof EGGS !== "undefined") {
  for (const _k of ["yanhua", "jujia"]) {
    if (EGGS[_k] && STORY.extras[_k]) STORY.extras[_k].nodes = EGGS[_k];
  }
}


/* ============================================================
   v0.16：选项呈现顺序
   ------------------------------------------------------------
   原先两条线 28 个选择点里有 17 个把「数值最优」的那一项固定排在
   第一格，于是「一路点第一个」正好凑出 hidden:gege 的门槛
   （好感 100 / 线索 5 / 执念 11）。

   这里只调呈现顺序，一个字都没改：
     label / favor / danger / clue / hint / branch 全部原样带走。
   每个选择点的可选集合不变 → 21 个结局的可达性严格不变。

   调完之后：
     · 最优项落在 首 / 中 / 末 = 7 / 11 / 10（打散前是 17 / 8 / 3）
     · 「一路点第一个」从 hidden:gege（100/5/11）掉到普通结局
     · 想拿 hidden:gege 必须专门规划路径，不再和默认点法重合

   PLAN[线][第几个选择点] = 新顺序，元素是**原下标**：
   读法 [2,1,0] = 原第 3 项、第 2 项、第 1 项。
   ============================================================ */
(function spreadOptionOrder() {
  if (STORY.__optsSpread) return;
  const PLAN = {
    wan: [
      [2, 1, 0], [1, 0, 2], [1, 0, 2], [2, 1, 0], [1, 0, 2], [2, 1, 0], [1, 0, 2],
      [1, 0, 2], [1, 0, 2], [2, 1, 0], [2, 1, 0], [1, 0, 2], [1, 0, 2], [2, 1, 0],
    ],
    jiang: [
      [0, 2, 1], [0, 2, 1], [2, 1, 0], [2, 1, 0], [1, 0, 2], [2, 1, 0], [1, 0, 2],
      [1, 0, 2], [1, 0], [0, 2, 1], [1, 0, 2], [1, 0, 2], [0, 2, 1], [1, 0, 2],
    ],
  };
  for (const line of Object.keys(PLAN)) {
    const qs = STORY.lines[line].filter(n => n.t === "choice");
    if (qs.length !== PLAN[line].length) {
      throw new Error("选项顺序表与选择点数不符：" + line + " " + qs.length + " vs " + PLAN[line].length);
    }
    qs.forEach((node, i) => {
      const perm = PLAN[line][i];
      if (perm.length !== node.opts.length) {
        throw new Error(line + " 第 " + (i + 1) + " 个选择点选项数不符：" + node.opts.length + " vs " + perm.length);
      }
      const before = node.opts.slice();
      node.opts = perm.map(k => before[k]);
    });
  }
  STORY.__optsSpread = true;
})();
